import { Component } from '@angular/core';
import { FormBuilder, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService } from '../../core/services/auth.service';

@Component({
  selector: 'app-register',
  templateUrl: './register.component.html',
  styleUrls: ['./register.component.scss']
})
export class RegisterComponent {
  form = this.fb.group({
    nombre:   ['', [Validators.required, Validators.minLength(2)]],
    email:    ['', [Validators.required, Validators.email]],
    password: ['', [Validators.required, Validators.minLength(6)]]
  });

  loading = false;
  error   = '';

  constructor(private fb: FormBuilder, private auth: AuthService, private router: Router) {}

  submit(): void {
    if (this.form.invalid || this.loading) return;
    this.loading = true;
    this.error   = '';

    this.auth.register(this.form.value as any).subscribe({
      next:  () => this.router.navigate(['/login']),
      error: (err) => {
        this.error   = err.error?.error ?? 'Error al registrarse.';
        this.loading = false;
      }
    });
  }
}
<div class="auth-page">
  <div class="auth-card card">
    <div class="auth-logo">🤝</div>
    <h2>Crear cuenta</h2>
    <p class="auth-sub">Únete a MisCompañeros</p>

    <div class="alert alert-error" *ngIf="error">{{ error }}</div>

    <form [formGroup]="form" (ngSubmit)="submit()">
      <div class="form-group">
        <label>Nombre</label>
        <input type="text" formControlName="nombre" placeholder="Tu nombre">
        <span class="error-msg"
          *ngIf="form.controls['nombre'].invalid && form.controls['nombre'].touched">
          Ingresa tu nombre (mínimo 2 caracteres).
        </span>
      </div>

      <div class="form-group">
        <label>Email</label>
        <input type="email" formControlName="email" placeholder="tu@email.com">
        <span class="error-msg"
          *ngIf="form.controls['email'].invalid && form.controls['email'].touched">
          Email inválido.
        </span>
      </div>

      <div class="form-group">
        <label>Contraseña</label>
        <input type="password" formControlName="password" placeholder="Mínimo 6 caracteres">
        <span class="error-msg"
          *ngIf="form.controls['password'].invalid && form.controls['password'].touched">
          La contraseña debe tener al menos 6 caracteres.
        </span>
      </div>

      <button type="submit" class="btn btn-primary full" [disabled]="loading">
        {{ loading ? 'Registrando...' : 'Crear cuenta' }}
      </button>
    </form>

    <p class="auth-link">
      ¿Ya tienes cuenta? <a routerLink="/login">Inicia sesión</a>
    </p>
  </div>
</div>
